  const target = String(n);
  const counts = new Array(10).fill(0);
  for (const ch of target) counts[Number(ch)]++;
  const chosen = [];
  // While tight, the arrangement so far equals n's prefix, so smaller digits would only give smaller numbers.
  const search = (tight) => {
    if (chosen.length === target.length) return tight ? null : chosen.join('');
    const low = tight ? Number(target[chosen.length]) : 0;
    for (let d = low; d <= 9; d++) {
      if (counts[d] === 0) continue;
      counts[d]--;
      chosen.push(d);
      const found = search(tight && d === low);
      chosen.pop();
      counts[d]++;
      if (found !== null) return found;
    }
    return null;
  };
  const found = search(true);
  if (found === null) return -1;
  return Number(found) <= 2147483647 ? Number(found) : -1;
}

